mapper.select:
SELECT usd_balance AS usd, btc_balance AS btc
FROM user_wallets
WHERE user_id = #{userId}

SELECT COALESCE(quantity, 0)
FROM portfolio_share_holdings
WHERE user_id = #{userId}
  AND artwork_id = #{artworkId}

mapper.update:
UPDATE user_wallets
SET usd_balance = usd_balance + #{delta}
WHERE user_id = #{userId}
  AND usd_balance + #{delta} >= 0

UPDATE user_wallets
SET btc_balance = btc_balance + #{delta}
WHERE user_id = #{userId}
  AND btc_balance + #{delta} >= 0

mapper.insert:
INSERT INTO trade_executions (
    artwork_id, buyer_user_id, seller_user_id, side, price, size, notional, source
) VALUES (
    #{artworkId}, #{buyerUserId}, #{sellerUserId}, #{side}, #{price}, #{size}, #{notional}, #{source}
)

INSERT INTO perp_positions (
    user_id, artwork_id, side, notional, leverage, entry_price, margin_btc
) VALUES (
    #{userId}, #{artworkId}, #{side}, #{notional}, #{leverage}, #{entryPrice}, #{marginBtc}
)

mapper.update:
UPDATE perp_positions
SET status = 'closed',
    closed_at = NOW()
WHERE user_id = #{userId}
  AND id = #{posId}
  AND status = 'open'

mapper.insert:
INSERT INTO tpsl_orders (
    user_id, artwork_id, type, perp_position_id, tp_price, sl_price, quantity
) VALUES (
    #{userId}, #{artworkId}, #{type}, #{posId}, #{tpPrice}, #{slPrice}, #{qty}
